-- Reference peer set: hand-verified filings, read and validated by the app's own import rules.
-- Generated by scripts/seed-reference-universe.ts from data/reference-universe/. NOT APPLIED: run it in the
-- Supabase SQL editor (safe to run twice). A company already present under the same name is left alone, and so
-- is a period already on file, so running it on a project that has its own copy of these companies adds nothing.

insert into sentinel_workspaces (owner_id, company_name, sector, industry, is_public_reference, fiscal_year_start_month, currency, currency_unit, comparison_basis)
select null, 'TCS', 'technology', 'IT services', true, 4, 'INR', 'INR_CRORE', 'consolidated'
where not exists (select 1 from sentinel_workspaces where lower(company_name) = lower('TCS'));

insert into sentinel_statements (workspace_id, period_type, period_label, period_end_date, basis, source_file, extraction_notes, revenue_from_operations, other_income, total_income, total_expenses, ebitda, depreciation_amortisation, finance_costs, exceptional_items, profit_before_tax, tax_expense, profit_after_tax, total_assets, current_assets, cash_and_equivalents, trade_receivables, fixed_assets, total_liabilities, current_liabilities, trade_payables, total_equity, cash_from_operations, cash_from_investing, cash_from_financing, capex)
select w.id, 'FY', 'FY26', '2026-03-31', 'consolidated', 'reference-universe seed', 'Hand-verified against the filing. Tata Consultancy Services, Integrated Annual Report 2025-26: consolidated balance sheet, profit and loss and cash flow (pp. 196-203). Hand-verified; balance sheet balances.', 267021, 4402, 271423, 201410, 72398, 5560, 1227, 4526, 65487, 16033, 49454, 182372, 135705, 6417, 67927, 11032, 73894, 60914, 14808, 108478, 52094, -12845, -42133, 3670 from sentinel_workspaces w
where w.is_public_reference and lower(w.company_name) = lower('TCS')
on conflict do nothing;

